def parse_duration(text: str) -> int:
    units = {
        'd': (1, 86400),
        'h': (2, 3600),
        'm': (3, 60),
        's': (4, 1),
    }

    i = 0
    n = len(text)
    total = 0
    last_order = 0
    found = False

    while i < n:
        digit_start = i
        while i < n and text[i].isdigit():
            i += 1

        if i == digit_start:
            raise ValueError("invalid duration")

        if i >= n or text[i] not in units:
            raise ValueError("invalid duration")

        unit = text[i]
        i += 1

        order, multiplier = units[unit]
        if order <= last_order:
            raise ValueError("invalid duration")

        last_order = order
        total += int(text[digit_start:i - 1]) * multiplier
        found = True

        if i == n:
            break

        if text[i].isspace():
            while i < n and text[i].isspace():
                i += 1
            if i == n:
                raise ValueError("invalid duration")

    if not found:
        raise ValueError("invalid duration")

    return total
```

