def compare_semver(a: str, b: str) -> int:
    def parse_version(s: str):
        # Strip build metadata (everything after '+')
        if '+' in s:
            s = s.split('+')[0]
        # Split off pre-release (everything after first '-')
        if '-' in s:
            core, pre = s.split('-', 1)
            pre_parts = pre.split('.')
        else:
            core = s
            pre_parts = None
        major, minor, patch = core.split('.')
        return int(major), int(minor), int(patch), pre_parts

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare core version numerically
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Core versions equal – compare pre-release
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1   # no pre-release is higher
    if pre_b is None:
        return -1  # pre-release is lower

    # Both have pre-release: compare identifier by identifier
    for i in range(min(len(pre_a), len(pre_b))):
        id_a = pre_a[i]
        id_b = pre_b[i]
        a_is_num = id_a.isdigit()
        b_is_num = id_b.isdigit()

        if a_is_num and b_is_num:
            # Numeric comparison
            num_a = int(id_a)
            num_b = int(id_b)
            if num_a < num_b:
                return -1
            if num_a > num_b:
                return 1
        elif a_is_num and not b_is_num:
            # Numeric is lower than alphanumeric
            return -1
        elif not a_is_num and b_is_num:
            return 1
        else:
            # Both alphanumeric: ASCII lexicographic order
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1

    # All compared identifiers equal – shorter pre-release is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0
```

