def lcs_length(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # Ensure m is the smaller dimension to reduce space
    if n < m:
        a, b = b, a
        n, m = m, n
    dp = [0] * (m + 1)
    for i in range(1, n + 1):
        prev = 0
        for j in range(1, m + 1):
            temp = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev + 1
            else:
                # dp[j] is the value from the previous row (top),
                # dp[j-1] is the value from the current row (left)
                if dp[j] < dp[j - 1]:
                    dp[j] = dp[j - 1]
            prev = temp
    return dp[m]
```

