def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # Ensure b is the shorter to minimize space
    if m < n:
        a, b = b, a
        m, n = n, m
    # Now n is the length of the shorter string
    prev = list(range(n + 1))
    curr = [0] * (n + 1)
    for i in range(1, m + 1):
        curr[0] = i
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j], curr[j - 1], prev[j - 1])
        prev, curr = curr, prev
    return prev[n]
```

